    async def refresh_session(self, input: RefreshSessionInput) -> TypedCommandResult[RefreshSessionOutcome]:
        raw = await self._transport._execute_command(
            contract_lineage=CONTRACT_LINEAGE, contract_version=CONTRACT_VERSION,
            command_name="RefreshSession", plan_hash=REFRESH_SESSION_PLAN_HASH,
            input=encode_record(input), attempts=self._command_attempts,
        )
        outcomes = {
            "SessionRefreshed": RefreshSessionSessionRefreshed,
            "RefreshSessionStale": RefreshSessionRefreshSessionStale,
            "RefreshSessionExpired": RefreshSessionRefreshSessionExpired,
            "RefreshSessionMissing": RefreshSessionRefreshSessionMissing,
            "RefreshSessionRevoked": RefreshSessionRefreshSessionRevoked,
        }
        result: TypedCommandResult[RefreshSessionOutcome] = raw._map_outcome(lambda value: decode_variant(outcomes, value))
        if not isinstance(result.outcome, RefreshSessionSessionRefreshed):
            return result._with_workflow_revisions(())
        if input.expected_revision >= 2**64 - 1:
            raise ValueError("RiffDB workflow successor revision overflow")
        return result._with_workflow_revisions((
            WorkflowSuccessorRevision(binding="session", revision=input.expected_revision + 1),
        ))

